import React from 'react';
import { Box, Table, TableBody, TableCell, TableContainer, TableHead, TableRow, Paper, Button } from '@mui/material';

const FranchiseListAdmin = () => {
  const franchises = [
    { name: 'Franchise A', location: 'New York', status: 'Active' },
    { name: 'Franchise B', location: 'Los Angeles', status: 'Inactive' },
    { name: 'Franchise C', location: 'Chicago', status: 'Active' }
  ];

  return (
    <Box sx={{ marginTop: 3 }}>
      <TableContainer component={Paper}>
        <Table sx={{ minWidth: 650 }} aria-label="Franchise List">
          <TableHead>
            <TableRow>
              <TableCell sx={{ fontWeight: 'bold' }}>Franchise Name</TableCell>
              <TableCell sx={{ fontWeight: 'bold' }}>Location</TableCell>
              <TableCell sx={{ fontWeight: 'bold' }}>Status</TableCell>
              <TableCell sx={{ fontWeight: 'bold' }}>Actions</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {franchises.map((franchise, index) => (
              <TableRow key={index}>
                <TableCell>{franchise.name}</TableCell>
                <TableCell>{franchise.location}</TableCell>
                <TableCell>{franchise.status}</TableCell>
                <TableCell>
                  <Button variant="outlined" color="primary" sx={{ marginRight: 1 }}>
                    Edit
                  </Button>
                  <Button variant="outlined" color="secondary">
                    Delete
                  </Button>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>
    </Box>
  );
};

export default FranchiseListAdmin;
